"""
Copyright & Content ID Claim Detection Module
Detects whether a YouTube video/song has active Content ID claims,
license attributions ('Licensed to YouTube by'), or official record label claims
BEFORE downloading it into production mixes.
"""

import os
import sys
import json
import re
import logging
import subprocess
from typing import Tuple, Dict, Any, Optional

logger = logging.getLogger("CopyrightChecker")

# Definitive Content ID markers placed automatically by YouTube's system
CONTENT_ID_PHRASES = [
    "licensed to youtube by",
    "provided to youtube by",
    "auto-generated by youtube",
    "music in this video",
    "on behalf of:",
    "record label",
    "exclusive licensee",
]

# Major Indian and International Record Labels that aggressively claim Content ID
MAJOR_CLAIMANTS = [
    "t-series", "super cassettes industries",
    "zee music", "zee entertainment",
    "sony music", "sme",
    "saregama",
    "tips official", "tips industries",
    "speed records",
    "wave music",
    "worldwide records",
    "venus worldwide",
    "yrf", "yash raj films",
    "times music",
    "believe music", "believe digital", "believe sas",
    "universal music", "umg",
    "warner music", "wmg",
    "the orchard music", "the orchard",
    "symphonic distribution",
    "aditya music", "lahari music", "geetha arts",
    "anand audio", "muzik 247", "dvocean",
]

# Cache to avoid re-checking the same video multiple times in a single session
_COPYRIGHT_CACHE: Dict[str, Tuple[bool, str]] = {}


def is_title_blacklisted(title: str) -> Tuple[bool, str]:
    """
    Fast pre-filter on video title: checks if an official label name is explicitly in the title.
    Returns (True, reason) if blacklisted, else (False, '').
    """
    t_lower = title.lower()
    for label in MAJOR_CLAIMANTS:
        # Match whole word boundary to avoid false positives
        pattern = rf"\b{re.escape(label)}\b"
        if re.search(pattern, t_lower):
            return True, f"Major record label detected in title: '{label}'"
    return False, ""


def check_video_copyright(video_id_or_url: str, timeout: int = 15) -> Tuple[bool, str]:
    """
    Checks if a YouTube video has active Content ID claims or record label licensing.
    Uses yt-dlp android client to fetch video metadata without downloading.
    Returns (is_claimed: bool, reason: str).
    """
    vid_id = video_id_or_url.split("v=")[-1].split("&")[0].split("?")[0].strip()
    if not vid_id:
        return False, "Invalid video ID"

    if vid_id in _COPYRIGHT_CACHE:
        return _COPYRIGHT_CACHE[vid_id]

    url = f"https://www.youtube.com/watch?v={vid_id}"

    cmd = [
        sys.executable, "-m", "yt_dlp",
        "--extractor-args", "youtube:player_client=android;player_skip=webpage",
        "--skip-download",
        "--no-warnings",
        "--quiet",
        "--dump-single-json",
        url,
    ]

    try:
        res = subprocess.run(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=timeout
        )

        if res.returncode != 0 or not res.stdout.strip():
            # If metadata fetch failed, do not block unless we have proof
            _COPYRIGHT_CACHE[vid_id] = (False, "Metadata extraction skipped")
            return False, "Metadata extraction skipped"

        data = json.loads(res.stdout)

        # 1. Check Content ID Metadata fields
        track = (data.get("track") or "").strip()
        artist = (data.get("artist") or "").strip()
        album = (data.get("album") or "").strip()

        if track and artist:
            reason = f"Content ID Audio Match: Track='{track}', Artist='{artist}'"
            if album:
                reason += f", Album='{album}'"
            _COPYRIGHT_CACHE[vid_id] = (True, reason)
            return True, reason

        # 2. Check Description for YouTube's automated copyright attribution
        desc = (data.get("description") or "").lower()

        for phrase in CONTENT_ID_PHRASES:
            if phrase in desc:
                # Find matching label if mentioned
                matched_label = ""
                for lbl in MAJOR_CLAIMANTS:
                    if lbl in desc:
                        matched_label = f" ({lbl.title()})"
                        break
                reason = f"Automated Copyright Claim detected in description: '{phrase}'{matched_label}"
                _COPYRIGHT_CACHE[vid_id] = (True, reason)
                return True, reason

        # Clean track - no Content ID or label claims detected
        _COPYRIGHT_CACHE[vid_id] = (False, "Clean (No Copyright Claims)")
        return False, "Clean (No Copyright Claims)"

    except subprocess.TimeoutExpired:
        logger.warning(f"Copyright check timed out for {vid_id} after {timeout}s")
        _COPYRIGHT_CACHE[vid_id] = (False, "Check timeout")
        return False, "Check timeout"
    except Exception as e:
        logger.debug(f"Copyright check exception for {vid_id}: {e}")
        _COPYRIGHT_CACHE[vid_id] = (False, str(e))
        return False, str(e)
